        if (!rst_ni) begin
            rst_n_sync_0 <= 1'b0;
            rst_n_sync_1 <= 1'b0;
        end else begin
            rst_n_sync_0 <= rst_ni;
            rst_n_sync_1 <= rst_n_sync_0;
